def query_trade_history(self, start_ts=None, end_ts=None, end_at_least_ts=None):
    exchange_data = self.api_query('exchangeInfo')
    symbols = []
    for symbol in exchange_data['symbols']:
        symbols.append(symbol['symbol'])

    #TODO: in progress
    trade_history = {}
    for symbol in symbols:
        trade_history[symbol] = self.api_query('tradeHistory', symbol=symbol, start_ts=start_ts, end_ts=end_ts, end_at_least_ts=end_at_least_ts)
    return trade_history
